import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../../shared/widgets/app_scaffold.dart';
import '../../../dashboard/presentation/providers/dashboard_providers.dart';
class CustomersScreen extends ConsumerStatefulWidget { const CustomersScreen({super.key}); @override ConsumerState<CustomersScreen> createState() => _CustomersState(); }
class _CustomersState extends ConsumerState<CustomersScreen> { final search = TextEditingController(); @override Widget build(BuildContext context) { final customers = ref.watch(customersProvider(search.text)); return AppScaffold(title: 'Customers', child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Row(children: [Expanded(child: TextField(controller: search, onChanged: (_) => setState(() {}), decoration: const InputDecoration(prefixIcon: Icon(Icons.search), hintText: 'Search by name or phone'))), const SizedBox(width: 12), FilledButton.icon(onPressed: () {}, icon: const Icon(Icons.person_add), label: const Text('New customer'))]), const SizedBox(height: 18), customers.when(data: (items) => Card(child: Column(children: items.map((c) => ListTile(title: Text(c.name), subtitle: Text(c.phone.isEmpty ? 'No phone number' : c.phone), leading: const CircleAvatar(child: Icon(Icons.person_outline)), trailing: Text('ZMW ${c.outstanding.toStringAsFixed(2)}', style: TextStyle(fontWeight: FontWeight.bold, color: c.outstanding > 0 ? Colors.red : Colors.green))).toList())), error: (e, _) => Text('Could not load customers: $e'), loading: () => const CircularProgressIndicator())])); } }
